package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

// Session is a row of the sessions table: a server-side session backing a
// secure HTTP-only cookie. The raw session token is never stored — only
// TokenHash, a hash of it.
type Session struct {
	ID        string
	UserID    string
	TokenHash string
	CreatedAt time.Time
	ExpiresAt time.Time
}

// NewSession holds the fields a caller supplies to CreateSession. ID and
// CreatedAt are generated by CreateSession itself.
type NewSession struct {
	UserID    string
	TokenHash string
	ExpiresAt time.Time
}

// CreateSession inserts a new session and returns it as stored.
func CreateSession(ctx context.Context, db *sql.DB, in NewSession) (Session, error) {
	id, err := newID()
	if err != nil {
		return Session{}, err
	}

	s := Session{
		ID:        id,
		UserID:    in.UserID,
		TokenHash: in.TokenHash,
		CreatedAt: time.Now().UTC(),
		ExpiresAt: in.ExpiresAt,
	}

	_, err = db.ExecContext(ctx, `
		INSERT INTO sessions (id, user_id, token_hash, created_at, expires_at)
		VALUES (?, ?, ?, ?, ?)`,
		s.ID, s.UserID, s.TokenHash, formatTime(s.CreatedAt), formatTime(s.ExpiresAt),
	)
	if err != nil {
		return Session{}, fmt.Errorf("insert session: %w", err)
	}

	return s, nil
}

// GetValidSessionByTokenHash looks up a session by its token hash and
// returns it only if, as of now: the session has not expired, and its
// owning user is active. Both checks happen in SQL so callers get one
// unambiguous ErrNotFound for "not usable" rather than having to
// separately re-check expiry/active themselves after a plain lookup.
func GetValidSessionByTokenHash(ctx context.Context, db *sql.DB, tokenHash string, now time.Time) (Session, error) {
	row := db.QueryRowContext(ctx, `
		SELECT s.id, s.user_id, s.token_hash, s.created_at, s.expires_at
		FROM sessions s
		JOIN users u ON u.id = s.user_id
		WHERE s.token_hash = ? AND s.expires_at > ? AND u.active = 1`,
		tokenHash, formatTime(now),
	)

	var (
		s         Session
		createdAt string
		expiresAt string
	)
	err := row.Scan(&s.ID, &s.UserID, &s.TokenHash, &createdAt, &expiresAt)
	if errors.Is(err, sql.ErrNoRows) {
		return Session{}, ErrNotFound
	}
	if err != nil {
		return Session{}, fmt.Errorf("scan session: %w", err)
	}

	if s.CreatedAt, err = parseTime(createdAt); err != nil {
		return Session{}, err
	}
	if s.ExpiresAt, err = parseTime(expiresAt); err != nil {
		return Session{}, err
	}

	return s, nil
}

// DeleteSessionByTokenHash deletes a session by its token hash (logout).
// Deleting a token hash that doesn't exist is not an error: logging out
// twice, or logging out an already-expired/purged session, should be a
// no-op rather than a failure.
func DeleteSessionByTokenHash(ctx context.Context, db *sql.DB, tokenHash string) error {
	if _, err := db.ExecContext(ctx, `DELETE FROM sessions WHERE token_hash = ?`, tokenHash); err != nil {
		return fmt.Errorf("delete session by token hash: %w", err)
	}
	return nil
}

// DeleteExpiredSessions deletes every session whose expires_at is at or
// before now, and returns the number of sessions removed. Intended to be
// called periodically to purge stale sessions.
func DeleteExpiredSessions(ctx context.Context, db *sql.DB, now time.Time) (int64, error) {
	res, err := db.ExecContext(ctx, `DELETE FROM sessions WHERE expires_at <= ?`, formatTime(now))
	if err != nil {
		return 0, fmt.Errorf("delete expired sessions: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("read rows affected: %w", err)
	}
	return n, nil
}

// DeleteSessionsByUserID deletes every session belonging to a user, e.g.
// to force logout everywhere on password change or deactivation.
func DeleteSessionsByUserID(ctx context.Context, db *sql.DB, userID string) error {
	if _, err := db.ExecContext(ctx, `DELETE FROM sessions WHERE user_id = ?`, userID); err != nil {
		return fmt.Errorf("delete sessions by user id: %w", err)
	}
	return nil
}
